CREATE TABLE proj_orders (order_id int, customer_id int, amount_cents int, status text);
CREATE TABLE proj_customers (customer_id int, segment text);
INSERT INTO proj_orders VALUES (1,1,1000,'paid'),(2,2,500,'paid'),(3,3,700,'paid'),(4,1,300,'failed'),(5,3,200,'paid'),(6,2,100,'refunded');
INSERT INTO proj_customers VALUES (1,'retail'),(2,'retail'),(3,'business');
SELECT c.segment, SUM(o.amount_cents) AS cents
FROM proj_orders o
JOIN proj_customers c ON c.customer_id = o.customer_id
WHERE o.status = 'paid'
GROUP BY c.segment
ORDER BY c.segment;

def reconcile(detail_total, plain_total, detail_count, plain_count):
    total_ok = detail_total == plain_total
    count_ok = detail_count == plain_count
    if total_ok and count_ok:
        return "OK"
    if count_ok:
        return "MISMATCH total"
    if total_ok:
        return "MISMATCH count"
    return "MISMATCH both"

print(reconcile(100, 100, 5, 5))
print(reconcile(100, 90, 5, 5))
print(reconcile(100, 90, 4, 5))
